"""IDX shell only. Live listing records never enter the static build or repository."""
def listing_search(t):
    def label(key,en,fr,control):
        return f'<div><label for="idx-{key}">{t(en,fr)}</label>'+control+'</div>'
    def select(key,choices):
        return f'<select id="idx-{key}" name="{key}">'+''.join(f'<option value="{v}">{t(en,fr)}</option>' for v,en,fr in choices)+'</select>'
    anychoice=[('','Any','Tous')]
    filters=label('deal','Looking to','Votre projet',select('deal',[('sale','Buy','Acheter'),('lease','Rent','Louer'),('all','Buy or rent','Acheter ou louer')]))
    for key,en,fr in [('min','Min. price ($)','Prix min. ($)'),('max','Max. price ($)','Prix max. ($)')]:
        filters+=label(key,en,fr,f'<input id="idx-{key}" name="{key}" type="number" min="0" max="1000000000" step="1" inputmode="numeric">')
    for key,en,fr in [('beds','Bedrooms','Chambres'),('baths','Bathrooms','Salles de bains')]:
        filters+=label(key,en,fr,select(key,anychoice+[(str(i),str(i)+'+',str(i)+'+') for i in range(1,6)]))
    filters+=label('type','Property type','Type de propriété',select('type',anychoice))
    filters+=label('sort','Sort by','Trier par',select('sort',[('newest','Newest listed','Annonces récentes'),('price-asc','Price: low to high','Prix croissant'),('price-desc','Price: high to low','Prix décroissant')]))
    return '''<link rel="stylesheet" href="/assets/listings.css?v=20261112"><script src="/assets/listings.js?v=20261112" defer></script><section class="wrap section idx-section" id="property-search"><div class="idx-heading"><div><p class="eyebrow">'''+t('A PLACE TO CALL HOME','UN CHEZ-SOI À NOBLETON')+'</p><h2>'+t('Discover what’s available.','Découvrez les propriétés disponibles.')+'</h2></div><a class="text-link" href="/ask-realtor/">'+t('Need help with your search?','Besoin d’aide pour votre recherche?')+'</a></div><form id="idx-filters" class="idx-filters" role="search" aria-label="'+t('Nobleton property search','Recherche de propriétés à Nobleton')+'">'+filters+'<div class="idx-filter-actions"><button class="button" type="submit">'+t('Find properties','Trouver des propriétés')+'</button><button class="text-link" type="reset">'+t('Reset filters','Réinitialiser')+'</button></div></form><p id="idx-status" role="status" aria-live="polite" tabindex="-1">'+t('Loading available properties…','Chargement des propriétés disponibles…')+'</p><p id="idx-updated" class="fine"></p><div id="idx-results" class="idx-grid"></div><div id="idx-pagination" class="idx-pagination"></div><noscript><p>'+t('Enable JavaScript to browse properties, or contact Ekaterina for a personal search.','Activez JavaScript pour explorer les propriétés ou contactez Ekaterina pour une recherche personnalisée.')+'</p></noscript><div class="idx-disclaimer"><p>'+t('Listing information is deemed reliable but is not guaranteed accurate by PropTx. Availability and details may change; confirm with your representative.','Les renseignements sont jugés fiables, mais leur exactitude n’est pas garantie par PropTx. La disponibilité et les détails peuvent changer; confirmez-les auprès de votre représentante.')+'</p><p>'+t('This search displays participating IDX listings in Nobleton, not the entire MLS® System. Listing content is displayed in the language supplied by the listing brokerage. For personal, non-commercial use by people with a genuine interest in buying, selling or leasing property.','Cette recherche présente les annonces IDX participantes à Nobleton, et non l’ensemble du système MLS®. Le contenu est présenté dans la langue fournie par la maison de courtage. Pour l’usage personnel et non commercial des personnes ayant un intérêt réel pour l’achat, la vente ou la location.')+'</p></div></section><section class="wrap section idx-agent"><img src="/assets/images/ekaterina-ottchenach.webp" width="180" height="220" alt="Ekaterina Ottchenach" loading="lazy"><div><p class="eyebrow">'+t('YOUR SEARCH, WITH LOCAL GUIDANCE','VOTRE RECHERCHE, AVEC UN ACCOMPAGNEMENT LOCAL')+'</p><h2>Ekaterina Ottchenach</h2><p>'+t('Real Estate Sales Representative','Représentante des ventes immobilières')+'<br>HomeLife Frontier Realty Inc., Brokerage<br>7620 Yonge St #400, Thornhill, ON L4J 1V9</p><div class="plan-actions"><a class="button" href="/ask-realtor/">'+t('Plan a showing','Planifier une visite')+'</a><a class="text-link" href="tel:+16478385569">(647) 838-5569</a><a class="text-link" href="mailto:realtor@nobleton.ca">realtor@nobleton.ca</a></div></div></section><dialog id="idx-detail" aria-labelledby="idx-detail-title"><button id="idx-close" type="button" class="idx-close" aria-label="'+t('Close property details','Fermer les détails de la propriété')+'">'+t('Close','Fermer')+' ×</button><div id="idx-detail-content"></div></dialog>'
